import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';

/** Build ordered, cache-busted modules and the legacy compatibility entrypoints. */
export function buildAdminStyles( root, outputRoot ) {
	const source = path.join( root, 'assets/src/admin-styles' );
	const destination = path.join( outputRoot, 'assets/dist/css/admin' );
	fs.mkdirSync( destination, { recursive: true } );
	const manifest = JSON.parse(
		fs.readFileSync( path.join( source, 'manifest.json' ), 'utf8' )
	);
	const combined = { main: '', rtl: '', ui: '' };
	const modules = manifest.map( ( entry ) => {
		const css = fs.readFileSync( path.join( source, entry.file ), 'utf8' );
		const layer = entry.layer || 'main';
		combined[ layer === 'ui' ? 'ui' : entry.rtl ? 'rtl' : 'main' ] += css;
		const hash = crypto
			.createHash( 'sha256' )
			.update( css )
			.digest( 'hex' )
			.slice( 0, 12 );
		const file = `oml-${ entry.file.replace( '.css', '' ) }.${ hash }.css`;
		const relative =
			layer === 'ui' ? 'assets/css' : 'assets/dist/css/admin';
		const targetDirectory = path.join( outputRoot, relative );
		fs.mkdirSync( targetDirectory, { recursive: true } );
		// Keep the original directory depth: vendor font/image URLs stay valid.
		fs.writeFileSync(
			path.join( targetDirectory, file ),
			css.replace( /\/\*# sourceMappingURL=.*?\*\//g, '' )
		);
		const inline =
			entry.group === 'shared' &&
			Buffer.byteLength( css ) <= 2048 &&
			! /url\s*\(|@import/i.test( css )
				? css
				: null;
		return {
			...entry,
			file,
			path: `${ relative }/${ file }`,
			layer,
			bytes: Buffer.byteLength( css ),
			inline,
		};
	} );
	fs.writeFileSync(
		path.join( destination, 'modules.json' ),
		JSON.stringify( modules, null, '\t' ) + '\n'
	);
	// PHP can require local metadata without a filesystem read/JSON decode per call.
	const php = modules
		.map(
			( entry ) =>
				`array( 'file' => '${ entry.file }', 'path' => '${ entry.path }', 'layer' => '${ entry.layer }', 'group' => '${ entry.group }', 'rtl' => ${ entry.rtl ? 'true' : 'false' }, 'inline' => ${ entry.inline === null ? 'null' : "'" + entry.inline.replace( /\\/g, '\\\\' ).replace( /'/g, "\\'" ) + "'" } )`
		)
		.join( ',\n' );
	fs.writeFileSync(
		path.join( destination, 'modules.php' ),
		`<?php\n// Generated by tools/build-admin-styles.mjs.\nreturn array(\n${ php }\n);\n`
	);
	fs.writeFileSync( path.join( destination, 'ohmylms.css' ), combined.main );
	fs.writeFileSync(
		path.join( outputRoot, 'assets/css/admin-ui.css' ),
		combined.ui
	);
	fs.writeFileSync(
		path.join( destination, 'ohmylms-rtl.css' ),
		combined.rtl
	);
	return modules;
}
